package br.com.luvi.financaspessoais.lancamento.service;import br.com.luvi.financaspessoais.conta.entity.ContaFinanceira;import br.com.luvi.financaspessoais.categoria.service.CategoriaService;import br.com.luvi.financaspessoais.conta.repository.ContaFinanceiraRepository;import br.com.luvi.financaspessoais.conta.service.ContaService;import br.com.luvi.financaspessoais.lancamento.dto.*;import br.com.luvi.financaspessoais.lancamento.entity.Lancamento;import br.com.luvi.financaspessoais.lancamento.enums.TipoLancamento;import br.com.luvi.financaspessoais.lancamento.repository.LancamentoRepository;import br.com.luvi.financaspessoais.transferencia.service.TransferenciaService;import br.com.luvi.financaspessoais.usuario.entity.Usuario;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.*;import java.util.*;
@Service public class LancamentoService{private final LancamentoRepository repo;private final ContaFinanceiraRepository contas;private final ContaService contaService;private final TransferenciaService transferencias;private final CategoriaService categorias;public LancamentoService(LancamentoRepository r,ContaFinanceiraRepository c,ContaService cs,TransferenciaService t,CategoriaService cat){repo=r;contas=c;contaService=cs;transferencias=t;categorias=cat;}private List<Long>ids(Usuario u,Long contaId,Long grupoId){if(contaId!=null){if(!contaService.podeAcessar(contaId,u))throw new SecurityException("Conta não permitida.");return List.of(contaId);}if(grupoId!=null)return contaService.doGrupo(grupoId,u).stream().map(ContaFinanceira::getId).toList();return contaService.acessiveis(u).stream().map(ContaFinanceira::getId).toList();}@Transactional public LancamentoResponse criar(LancamentoRequest req,Usuario u){Lancamento l=new Lancamento();atualizarCampos(l,req,u);l.setUsuarioCriacao(u);return LancamentoResponse.from(repo.save(l));}@Transactional(readOnly=true)public List<LancamentoResponse>listar(int mes,int ano,Long contaId,Long grupoId,Usuario u){List<Long>ids=ids(u,contaId,grupoId);if(ids.isEmpty())return List.of();YearMonth ym=YearMonth.of(ano,mes);return repo.findByContaIdInAndDataBetweenOrderByDataDescDataHoraCadastroDescIdDesc(ids,ym.atDay(1),ym.atEndOfMonth()).stream().map(LancamentoResponse::from).toList();}@Transactional(readOnly=true)public ResumoMensalResponse resumo(int mes,int ano,Long contaId,Long grupoId,Usuario u){List<Long>ids=ids(u,contaId,grupoId);if(ids.isEmpty())return new ResumoMensalResponse(BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO);YearMonth ym=YearMonth.of(ano,mes);LocalDate i=ym.atDay(1),f=ym.atEndOfMonth();BigDecimal ra=repo.somarAntesDe(ids,TipoLancamento.RECEITA,i),da=repo.somarAntesDe(ids,TipoLancamento.DESPESA,i),r=repo.somarNoPeriodo(ids,TipoLancamento.RECEITA,i,f),d=repo.somarNoPeriodo(ids,TipoLancamento.DESPESA,i,f);BigDecimal transfAntes=transferencias.saldoAntes(ids,i),transfPeriodo=transferencias.saldoPeriodo(ids,i,f);BigDecimal si=ra.subtract(da).add(transfAntes);if(contaId!=null){BigDecimal entradas=transferencias.entradas(contaId,i,f),saidas=transferencias.saidas(contaId,i,f);BigDecimal receitasConta=r.add(entradas),despesasConta=d.add(saidas),mov=receitasConta.subtract(despesasConta);return new ResumoMensalResponse(si,receitasConta,despesasConta,mov,si.add(mov));}BigDecimal movReceitaDespesa=r.subtract(d),sf=si.add(movReceitaDespesa).add(transfPeriodo);return new ResumoMensalResponse(si,r,d,movReceitaDespesa.add(transfPeriodo),sf);}@Transactional public LancamentoResponse atualizar(Long id,LancamentoRequest req,Usuario u){Lancamento l=repo.findById(id).orElseThrow();if(l.getConta()!=null&&!contaService.podeAcessar(l.getConta().getId(),u))throw new SecurityException("Acesso negado.");atualizarCampos(l,req,u);return LancamentoResponse.from(repo.save(l));}@Transactional public void excluir(Long id,Usuario u){Lancamento l=repo.findById(id).orElseThrow();if(l.getConta()!=null&&!contaService.podeAcessar(l.getConta().getId(),u))throw new SecurityException("Acesso negado.");repo.delete(l);}private void atualizarCampos(Lancamento l,LancamentoRequest r,Usuario u){if(!contaService.podeAcessar(r.contaId(),u))throw new SecurityException("Conta não permitida.");l.setConta(contas.findById(r.contaId()).orElseThrow());l.setTipo(r.tipo());l.setDescricao(r.descricao().trim());var cat=categorias.obter(r.categoriaId(),u);if(cat.getTipo()!=r.tipo())throw new IllegalStateException("A categoria selecionada não pertence ao tipo do lançamento.");l.setCategoria(cat);l.setValor(r.valor());l.setData(r.data());}}
